// =============================================================================
// tb_chat : a whole conversation generated by nslm_core (autoregressive, on chip)
//   gen/chat.mem script: byte < 64 -> push that symbol; 0xC0 -> generate until the
//   model outputs a newline, then compare every generated symbol with the expected
//   bytes that follow, up to 0xFF. The context carries over between questions.
//   Prints the generated conversation as text and the clocks per character.
// =============================================================================
`timescale 1ns/1ps
module tb_chat;
    `include "num_vectors.vh"
    reg clk = 0;
    always #18.518 clk = ~clk;

    reg push = 0, start = 0, gen = 0;
    reg [5:0] sym = 0;
    wire busy, done;
    wire [5:0] nsym;
    wire [335:0] logits;
    wire [191:0] ctx;
    nslm_core dut (.clk(clk), .push(push), .sym_in(sym), .start(start), .gen(gen), .busy(busy),
                   .done(done), .next_sym(nsym), .logits(logits), .ctx(ctx));

    reg [7:0] script [0:N_CHAT-1];
    reg [7:0] alpha [0:41];
    integer pc = 0, errors = 0, chars = 0, cyc = 0, total_cyc = 0, n, fd;
    initial begin
        $readmemh("chat.mem", script);
        // "\n :,.?abcdefghijklmnopqrstuvwxyz0123456789"
        alpha[0] = 8'h0A; alpha[1] = " "; alpha[2] = ":"; alpha[3] = ","; alpha[4] = "."; alpha[5] = "?";
        for (n = 0; n < 26; n = n + 1) alpha[6 + n] = "a" + n;
        for (n = 0; n < 10; n = n + 1) alpha[32 + n] = "0" + n;
        fd = $fopen("chat_generated.txt", "w");
        repeat (3) @(negedge clk);
        while (pc < N_CHAT) begin
            if (script[pc] < 8'd64) begin                    // push a prompt symbol
                sym = script[pc][5:0]; push = 1; @(negedge clk); push = 0;
                $fwrite(fd, "%c", alpha[script[pc]]);
                pc = pc + 1;
            end else begin                                   // 0xC0: generate the answer
                pc = pc + 1;
                while (script[pc] != 8'hFF) begin
                    gen = 1; @(negedge clk); gen = 0; cyc = 1;
                    while (!done) begin @(negedge clk); cyc = cyc + 1; end
                    total_cyc = total_cyc + cyc; chars = chars + 1;
                    $fwrite(fd, "%c", alpha[nsym]);
                    if (nsym !== script[pc][5:0]) begin
                        errors = errors + 1;
                        if (errors < 5) $display("MISMATCH at script byte %0d: got %0d expected %0d", pc, nsym, script[pc]);
                    end
                    pc = pc + 1;
                    @(negedge clk);
                end
                pc = pc + 1;
            end
        end
        $fclose(fd);
        $display("RESULT chat generated_chars=%0d mismatches=%0d clocks_per_char=%0d %s",
                 chars, errors, total_cyc / chars, errors == 0 ? "PASS" : "FAIL");
        $finish;
    end
endmodule
